concepts.codeExample:
class CoffeeMachine {
  makeCoffee() {
    this.#heatWater();
    this.#brew();
    return 'Coffee ready';
  }

  #heatWater() {
    return 'Heating water';
  }

  #brew() {
    return 'Brewing';
  }
}

const machine = new CoffeeMachine();
console.log(machine.makeCoffee());

concepts.tryItCode:
class PaymentService {
  pay(amount) {
    return this.#send(amount);
  }

  #send(amount) {
    return `Sent ${amount}`;
  }
}

console.log(new PaymentService().pay(50));
